CREATE TABLE IF NOT EXISTS seo (
  id SERIAL PRIMARY KEY,
  page_path TEXT UNIQUE NOT NULL,
  title TEXT,
  description TEXT,
  keywords TEXT,
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE seo ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated users can read seo" ON seo
  FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Authenticated users can insert seo" ON seo
  FOR INSERT WITH CHECK (auth.role() = 'authenticated');

CREATE POLICY "Authenticated users can update seo" ON seo
  FOR UPDATE USING (auth.role() = 'authenticated');

CREATE POLICY "Authenticated users can delete seo" ON seo
  FOR DELETE USING (auth.role() = 'authenticated');

-- Allow public read (for server-side rendering without auth)
CREATE POLICY "Public can read seo" ON seo
  FOR SELECT USING (true);

